-- 秒杀预检脚本：库存判断 + 一人一单 + 预扣
-- KEYS[1] 库存key：seckill:stock:{voucherId}
-- KEYS[2] 已下单用户集合key：seckill:order:{voucherId}
-- ARGV[1] 用户id
-- 返回：0=通过并已预扣；1=库存不足；2=重复下单
--先判断库存是否充足
local stock = redis.call('get', KEYS[1])
--判断秒杀是否开始
local now=redis.call('time')[1]*1000
local begin=redis.call('get' ,KEYS[3])
local finish= redis.call('get',KEYS[4])
if( begin and tonumber(now) < tonumber(begin) ) then
    return 3
end
if (finish and tonumber(now) > tonumber(finish)) then
    return 4
end
--not stock:判断stock是不是nil
--tonumber(stock):把字符串转成数字
if (not stock or tonumber(stock) <= 0) then
    return 1
end
--判断用户id:ARGV[1]是不是在集合KEYS[2]里面
if (redis.call('sismember', KEYS[2], ARGV[1]) == 1) then
    return 2
end

--执行减库存的操作
redis.call('incrby', KEYS[1], -1)
--把下单的用户id加入已下单的名单里
redis.call('sadd', KEYS[2], ARGV[1])
return 0